import{_ as a,o as e,c as o,a0 as n}from"./chunks/framework.veCcaNqE.js";const f=JSON.parse('{"title":"二次模型中的线性函数组合","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/guide/quadratic-functional/linear-compositions.md","filePath":"zh-cn/guide/quadratic-functional/linear-compositions.md"}'),i={name:"zh-cn/guide/quadratic-functional/linear-compositions.md"};function d(r,t,c,l,s,h){return e(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="二次模型中的线性函数组合" tabindex="-1">二次模型中的线性函数组合 <a class="header-anchor" href="#二次模型中的线性函数组合" aria-label="Permalink to &quot;二次模型中的线性函数组合&quot;">​</a></h1><p>线性模型函数与二次模型函数的用途不同。线性输入函数生成的行通常仍是线性的，因此可以在二次模型中复用。接收二次多项式输入的函数则是在非线性输入上组合相同运算，可能引入二次等式。</p><h2 id="复用线性输入函数" tabindex="-1">复用线性输入函数 <a class="header-anchor" href="#复用线性输入函数" aria-label="Permalink to &quot;复用线性输入函数&quot;">​</a></h2><p>线性表达式可作为二次目标和约束的组成部分。若输入为线性表达式且生成约束仍为线性，<code>MinFunction</code>、<code>MaxFunction</code>、<code>AbsFunction</code>、<code>MaskingFunction</code>、<code>IfFunction</code> 和精确组合函数等线性函数可直接复用。它们仍遵循普通 MILP 的精确性与有限界要求，包括<a href="./../linear-functional/composite-cardinality.html">基数、正部、区间裁剪、互补和距离函数</a>、<a href="./../linear-functional/order-statistics.html">顺序统计</a>及<a href="./../linear-functional/risk-global-constraints.html">CVaR</a>。Rust 中，涉及辅助变量的表达式应通过所属符号提供的注册 solver-index 映射生成。</p><p><code>ProductFunction</code> 将两个线性表达式相乘并返回二次表达式，不创建结果变量，也不做线性化。需要支持二次表达式的求解器。</p><p><code>QuadraticLinearFunction</code> 通过等式将二次表达式绑定到可正可负的实辅助变量，使该值能复用于线性输入函数接口。此等式本身是二次的，因此模型为 MIQCP，且可能非凸。</p><h2 id="对二次输入组合函数" tabindex="-1">对二次输入组合函数 <a class="header-anchor" href="#对二次输入组合函数" aria-label="Permalink to &quot;对二次输入组合函数&quot;">​</a></h2><p><code>QuadraticAbsFunction</code>、<code>QuadraticMaxFunction</code>、<code>QuadraticMinMaxFunction</code>、<code>QuadraticMaskingFunction</code> 和 <code>QuadraticIfFunction</code> 等二次对应函数可对二次输入多项式执行熟悉的函数语义。每个实际含二次项的输入都由可正可负的桥接变量及精确二次等式表示；仿射输入无需桥接。之后函数内部的线性化约束使用桥接值构造。</p><p>这样可以避免把两个二次表达式继续相乘，产生三次或四次项。模型仍然不是线性的：它会包含 MIQCP 约束，应使用支持所需二次约束的求解器。整个模型决定凸性与性能。</p><h2 id="模型保证" tabindex="-1">模型保证 <a class="header-anchor" href="#模型保证" aria-label="Permalink to &quot;模型保证&quot;">​</a></h2><table tabindex="0"><thead><tr><th>构造</th><th>保证</th><th>求解器/模型类别</th></tr></thead><tbody><tr><td>有界整数乘积或精确选择器</td><td>对任意目标方向均精确</td><td>MILP</td></tr><tr><td>连续因子的 McCormick 包络</td><td>在声明的矩形域上为凸包松弛</td><td>LP/MILP 松弛</td></tr><tr><td>非线性分段函数</td><td>断点间按给定点线性插值；无自动误差界</td><td>含分段选择变量的 MILP</td></tr><tr><td>CVaR 精确候选枚举</td><td>对任意目标方向均精确</td><td>MILP</td></tr><tr><td>CVaR 上图</td><td>最小化时在最优解处收紧；结果上界精确表达 <code>CVaR &lt;= limit</code> 的可行性，但不强制数值相等</td><td>LP/MILP 上图</td></tr><tr><td>二次桥接等式</td><td>与二次输入精确相等</td><td>MIQCP，可能非凸</td></tr></tbody></table><p>应按所需语义选择构造。松弛可用于界或分解，但不能称为精确乘积；PWL 模型近似原曲线；CVaR 上图表达式只有在被最小化时才会在最优解处收紧，结果上界保留精确的风险可行性判断，但不固定辅助表达式等于 CVaR；二次桥接保留等式语义但会改变求解器类别。</p><p>参见<a href="./product.html">乘积表达式</a>、<a href="./quadratic-abs.html">二次输入函数</a>，以及线性模型中的<a href="./../linear-functional/composite-cardinality.html">组合函数、基数与距离</a>、<a href="./../linear-functional/order-statistics.html">顺序统计</a>、<a href="./../linear-functional/slack-range.html">松弛区间</a>、<a href="./../linear-functional/products-selection.html">乘积与选择</a>、<a href="./../linear-functional/nonlinear-tariffs.html">非线性近似与阶梯计费</a>和<a href="./../linear-functional/risk-global-constraints.html">风险度量与全局约束</a>。</p>',13)])])}const p=a(i,[["render",d]]);export{f as __pageData,p as default};
